final class TrabajoMemoria implements TrabajoRepository
{
    public array $tareas=[];public array $planillas=[];public function listarTareas():array{return array_values($this->tareas);}public function responsableValido(?Cedula $c):bool{return $c===null||in_array($c->value(),['57324099','66666666'],true);}
    public function crearTarea(array $d,?Cedula $c):int{$id=count($this->tareas)+1;$this->tareas[$id]=['id_tarea'=>$id,'titulo_tarea'=>$d['titulo'],'descripcion_tarea'=>$d['descripcion'],'plazo_tarea'=>$d['plazo'],'categoria_tarea'=>$d['categoria'],'dificultad_tarea'=>$d['dificultad'],'estado_tarea'=>$d['estado'],'color_tarea'=>$d['color'],'fecha_agregada'=>'2026-10-19','tecnico_cedula'=>$c?$c->value():null];return $id;}public function actualizarTarea(int $id,array $d,?Cedula $c):bool{if(!isset($this->tareas[$id]))return false;$this->tareas[$id]=array_merge($this->tareas[$id],['titulo_tarea'=>$d['titulo'],'descripcion_tarea'=>$d['descripcion'],'plazo_tarea'=>$d['plazo'],'categoria_tarea'=>$d['categoria'],'dificultad_tarea'=>$d['dificultad'],'estado_tarea'=>$d['estado'],'color_tarea'=>$d['color'],'tecnico_cedula'=>$c?$c->value():null]);return true;}public function eliminarTarea(int $id):bool{if(!isset($this->tareas[$id]))return false;unset($this->tareas[$id]);return true;}
