function assertT(bool $c,string $m):void{if(!$c)throw new RuntimeException($m);}function rechazaT(callable $accion,string $m):void{try{$accion();}catch(\Nexus\Shared\DomainException){return;}throw new RuntimeException($m);}$r=new TrabajoMemoria();$s=new TrabajoService($r);$tecnico=new Cedula('66666666');$admin=new Cedula('57324099');$d=['titulo'=>'Revisar laboratorio','descripcion'=>'Comprobar los equipos.','plazo'=>(new DateTimeImmutable('+7 days'))->format('Y-m-d'),'categoria'=>'Mantenimiento','dificultad'=>'Media','estado'=>'Pendiente','color'=>'#00A7B9','tecnico'=>$tecnico];$id=$s->crearTarea($d);assertT($id===1,'Alta de tarea falló.');$d['estado']='En revision';$d['dificultad']='Alta';$s->actualizarTarea($id,$d);assertT($r->tareas[1]['estado_tarea']==='En revision'&&$r->tareas[1]['dificultad_tarea']==='Alta','Edición o En revisión falló.');$d['estado']='En curso';$s->actualizarTarea($id,$d);assertT($s->tareas()[0]['estado']==='En curso','Movimiento Kanban falló.');$invalida=$d;$invalida['descripcion']='';rechazaT(fn()=>$s->crearTarea($invalida),'Aceptó una tarea sin descripción.');$invalida=$d;$invalida['dificultad']='Urgente';rechazaT(fn()=>$s->crearTarea($invalida),'Aceptó una dificultad fuera del contrato.');$invalida=$d;$invalida['color']='azul';rechazaT(fn()=>$s->crearTarea($invalida),'Aceptó un color inválido.');$s->guardarPlanilla($tecnico,$tecnico,false,['tareas'=>'Revisión de equipos','entrada'=>'08:00','salida'=>'16:00']);$s->guardarPlanilla($admin,$admin,true,['tareas'=>'Administración','entrada'=>'09:00','salida'=>'17:00']);assertT(count($s->planillas())===2,'Técnico no puede ver todas las planillas.');$s->eliminarTarea($id);assertT(!$r->tareas,'Eliminación de tarea falló.');echo "OK: 14 comportamientos de tareas y planillas verificados.\n";
